package nphttp2

// ServiceProtocol defines the transport-level protocol for RPC communication
type ServiceProtocol int32

const (
	// Unknown represents an undefined or unrecognized protocol
	Unknown ServiceProtocol = 0

	// PingPong represents traditional request-response pattern (default)
	PingPong ServiceProtocol = 1

	// Oneway represents fire-and-forget pattern (no response expected)
	Oneway ServiceProtocol = 2

	// StreamingUnary represents unary calls over streaming transport
	StreamingUnary ServiceProtocol = 3

	// ServerStreaming represents server-side streaming (one request, multiple responses)
	ServerStreaming ServiceProtocol = 4

	// ClientStreaming represents client-side streaming (multiple requests, one response)
	ClientStreaming ServiceProtocol = 5

	// BidiStreaming represents bidirectional streaming (multiple requests and responses)
	BidiStreaming ServiceProtocol = 6
)

