	switch p {
	case Unknown:
		return "Unknown"
	case PingPong:
		return "PingPong"
	case Oneway:
		return "Oneway"
	case StreamingUnary:
		return "StreamingUnary"
	case ServerStreaming:
		return "ServerStreaming"
	case ClientStreaming:
		return "ClientStreaming"
	case BidiStreaming:
		return "BidiStreaming"
	default:
		return "Unknown"
	}
}

