// A Suite is a collection of Options. It is useful to assemble multiple associated
// Options as a single one to keep the order or presence in a desired manner.
type Suite interface {
	Options() []Option
}

// TailOption is an option that is applied after all other options.
// It is useful for post-configuration hooks or validation logic that depends
// on the final state of all options.
type TailOption struct {
	F func(o *client.Options)
}

// WithTailOption adds a tail option that executes after all other options.
// Tail options are useful for:
// - Final validation of option combinations
// - Post-processing of accumulated configuration
// - Setting derived values based on multiple options
func WithTailOption(f func(o *client.Options)) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithTailOption(%+v)", utils.GetFuncName(f)))
		// Store tail function to be executed after all options
		if o.TailOptions == nil {
			o.TailOptions = make([]func(*client.Options), 0)
		}
		o.TailOptions = append(o.TailOptions, f)
	}}
}

